CREATE TABLE IF NOT EXISTS roles (id SMALLSERIAL PRIMARY KEY, name VARCHAR(20) NOT NULL UNIQUE CHECK (name IN ('ADMIN','USER')));
INSERT INTO roles(name) VALUES ('ADMIN'), ('USER') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role_id SMALLINT NOT NULL REFERENCES roles(id), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS activities (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, activity_date DATE NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL DEFAULT '', priority VARCHAR(10) NOT NULL CHECK (priority IN ('HIGH','MEDIUM','LOW')), status VARCHAR(15) NOT NULL CHECK (status IN ('PENDING','IN_PROGRESS','COMPLETED')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS activities_user_date_idx ON activities(user_id, activity_date);
CREATE INDEX IF NOT EXISTS activities_date_idx ON activities(activity_date);
